// Assets from the approved report design (report_customer-edited.html). Do not edit by hand; keep in sync with that file.
export const REPORT_CSS = ":root{--paper:#f4f6f7;--card:#fff;--fg:#16202b;--mut:#5b6774;--line:#e1e6ea;--soft:#eef2f3;\n--ink:#0d1328;--ink2:#151d3a;--brand:#13e989;--mint:#86ffc9;--brand-text:#08875a;\n--c-logs:#0e9aa7;--c-traces:#6b4fd8;--c-metrics:#c98a00;\n--ph1:#13b873;--ph2:#e0a100;--ph3:#e2712b;--warn-bg:#fff7e0;--warn-line:#e0a100;--info-bg:#eaf8f2;--info-line:#13b873;\n--code-bg:#0f1530;--code-fg:#dfe6f3;color-scheme:light}\n@media (prefers-color-scheme:dark){:root{--paper:#0b1020;--card:#131a30;--fg:#e7ecf3;--mut:#9aa7b8;--line:#253050;--soft:#18213b;\n--brand-text:#4ff0a8;--c-logs:#3fc3cf;--c-traces:#9d86ff;--c-metrics:#f0b43a;--warn-bg:#2a2410;--info-bg:#10261f;--code-bg:#090d1c;color-scheme:dark}}\n*{box-sizing:border-box}html{scroll-behavior:smooth}\nbody{margin:0;background:var(--paper);color:var(--fg);font:15.5px/1.6 \"Manrope\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;-webkit-font-smoothing:antialiased}\ncode,pre{font-family:\"JetBrains Mono\",\"SF Mono\",Menlo,Consolas,monospace;font-variant-ligatures:none}\na{color:var(--brand-text);text-underline-offset:2px}\n.wrap{max-width:1060px;margin:0 auto;padding:0 28px}\n/* header */\n.top{background:radial-gradient(1200px 400px at 85% -10%,rgba(19,233,137,.18),transparent 60%),var(--ink);color:#fcfcfc;padding:28px 0 0}\n.top .bar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}\n.logo{height:30px;width:auto;color:#fcfcfc}\n.brandline{display:flex;align-items:center;gap:14px}.brandline .prod{font-weight:600;color:var(--mint);border-left:1px solid rgba(255,255,255,.2);padding-left:14px;font-size:15px}\n.draft{background:rgba(224,161,0,.16);color:#ffd36b;border:1px solid rgba(224,161,0,.45);border-radius:999px;padding:4px 12px;font-size:13px;font-weight:600}\n.top h1{font-size:clamp(28px,4.4vw,44px);line-height:1.12;letter-spacing:-.02em;margin:46px 0 10px;font-weight:800;max-width:760px}\n.top .lede{color:#b9c3d6;max-width:680px;margin:0 0 28px;font-size:16px}\n.facts{display:flex;flex-wrap:wrap;gap:0;border-top:1px solid rgba(255,255,255,.12);margin-top:8px}\n.facts div{padding:14px 28px 16px 0;margin-right:28px}.facts span{display:block;font-size:12.5px;color:#8b97ad}.facts b{font-weight:600}\nnav.toc{background:var(--ink2);position:sticky;top:0;z-index:5;border-bottom:1px solid rgba(255,255,255,.06)}\nnav.toc .wrap{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none}\nnav.toc a{color:#c7d0e0;text-decoration:none;font-size:13.5px;font-weight:600;padding:12px 12px;white-space:nowrap;border-bottom:2px solid transparent}\nnav.toc a:hover,nav.toc a:focus-visible{color:#fff;border-color:var(--brand);outline:none}\n/* sections */\nsection{padding:56px 0 8px}\nh2{font-size:24px;letter-spacing:-.015em;margin:0 0 6px;font-weight:800}\n.sec-sub{color:var(--mut);margin:0 0 24px;max-width:720px}\nh3{font-size:18px;margin:36px 0 14px;display:flex;align-items:center;gap:10px}\n.muted{color:var(--mut)}\n/* savings hero */\n.hero{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:30px 32px;margin-top:-1px}\n.hero-top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:20px}\n.big{font-size:clamp(48px,8vw,84px);font-weight:800;letter-spacing:-.04em;line-height:.95;color:var(--brand-text)}\n.big small{font-size:.32em;letter-spacing:0;font-weight:700;color:var(--fg);margin-left:10px}\n.hero p{margin:10px 0 0;color:var(--mut);max-width:520px}\n.fromto{text-align:right}.fromto b{font-size:22px}.fromto span{display:block;color:var(--mut);font-size:13px}\n.meter{position:relative;height:46px;border-radius:10px;background:var(--soft);margin:26px 0 10px;overflow:hidden;display:flex}\n.meter .keep{width:60.2%;background:var(--ink);color:#fcfcfc;display:flex;align-items:center;padding:0 16px;font-size:13.5px;font-weight:600}\n.meter .save{flex:1;background:repeating-linear-gradient(-45deg,var(--brand) 0 8px,var(--mint) 8px 16px);color:#06301d;display:flex;align-items:center;justify-content:flex-end;padding:0 16px;font-size:13.5px;font-weight:700}\n@media (prefers-color-scheme:dark){.meter .keep{background:#2b3760}}\n.meter-scale{display:flex;justify-content:space-between;color:var(--mut);font-size:12.5px}\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-top:18px}\n.stat{background:var(--card);padding:18px 20px}.stat span{color:var(--mut);font-size:13px;display:block}.stat b{font-size:26px;letter-spacing:-.02em}.stat em{font-style:normal;color:var(--mut);font-size:13px;margin-left:4px}\n/* intro */\n.intro{display:grid;grid-template-columns:1.4fr 1fr;gap:28px;align-items:start}\n.intro p{margin:0 0 12px}\n.unit-card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px;font-size:14px}\n.unit-card b.eq{display:block;font-size:22px;margin:4px 0;color:var(--fg)}\n/* roadmap */\n.road{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;counter-reset:ph}\n.phase{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px;position:relative;border-top:5px solid var(--pc)}\n.phase.ph1{--pc:var(--ph1)}.phase.ph2{--pc:var(--ph2)}.phase.ph3{--pc:var(--ph3)}\n.phase .pn{font-size:13px;font-weight:700;color:var(--pc)}\n.phase h4{margin:2px 0 8px;font-size:19px}\n.phase p{margin:0 0 16px;color:var(--mut);font-size:14px;min-height:64px}\n.phase dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:0 0 16px;font-size:13.5px}.phase dt{color:var(--mut)}.phase dd{margin:0;font-weight:600}\n.cum{font-size:12.5px;color:var(--mut)}.cum b{display:block;font-size:22px;color:var(--fg)}\n.cum .track{height:8px;background:var(--soft);border-radius:4px;margin-top:8px;overflow:hidden}.cum .track i{display:block;height:100%;background:var(--pc);border-radius:4px}\n.callout{display:flex;gap:14px;align-items:flex-start;background:var(--info-bg);border:1px solid color-mix(in srgb,var(--info-line) 40%,transparent);border-radius:14px;padding:16px 20px;margin-top:18px}\n.callout .ic{flex:none;width:28px;height:28px;border-radius:50%;background:var(--info-line);color:#fff;display:grid;place-items:center;font-weight:800}\n.callout p{margin:0}\n.callout.warn{background:var(--warn-bg);border-color:color-mix(in srgb,var(--warn-line) 45%,transparent)}.callout.warn .ic{background:var(--warn-line)}\n/* version */\n.versions{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}\n.ver{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px;display:flex;justify-content:space-between;align-items:center;gap:12px}\n.ver span{color:var(--mut);font-size:13px;display:block}.ver b{font-family:\"JetBrains Mono\",monospace;font-size:17px}\n.ok{background:var(--info-bg);color:var(--brand-text);font-weight:700;font-size:12.5px;border-radius:999px;padding:4px 10px;white-space:nowrap}\n.ver-foot{color:var(--mut);font-size:13.5px;margin-top:12px}\n/* tables */\n.tbl{overflow-x:auto;background:var(--card);border:1px solid var(--line);border-radius:14px}\ntable{border-collapse:collapse;width:100%;font-size:14px;font-variant-numeric:tabular-nums}\nth{text-align:left;font-size:12.5px;color:var(--mut);font-weight:600;padding:12px 14px;border-bottom:1px solid var(--line);background:var(--soft);white-space:nowrap}\ntd{padding:14px;border-bottom:1px solid var(--line);vertical-align:top}tr:last-child td{border-bottom:0}\ntd.num{color:var(--mut);font-weight:700}\n.rank tbody tr:hover{background:var(--soft)}\n.rk-title{font-weight:600;line-height:1.35}.rk-vol{color:var(--mut);font-size:12.5px;margin-top:3px;max-width:380px}\n.fid{font-family:\"JetBrains Mono\",monospace;font-size:12.5px;font-weight:600;background:var(--soft);border:1px solid var(--line);color:var(--fg);padding:2px 7px;border-radius:6px;text-decoration:none;white-space:nowrap}\na.fid:hover{border-color:var(--brand)}\n.pill{display:inline-block;font-size:12px;font-weight:700;padding:3px 9px;border-radius:999px;white-space:nowrap}\n.p-traces{background:color-mix(in srgb,var(--c-traces) 14%,transparent);color:var(--c-traces)}\n.p-metrics{background:color-mix(in srgb,var(--c-metrics) 16%,transparent);color:var(--c-metrics)}\n.e-low{background:color-mix(in srgb,var(--ph1) 15%,transparent);color:var(--brand-text)}\n.e-med{background:color-mix(in srgb,var(--ph2) 18%,transparent);color:var(--c-metrics)}\n.status{font-size:12.5px;font-weight:600;white-space:nowrap;display:inline-flex;align-items:center;gap:6px}\n.status::before{content:\"\";width:8px;height:8px;border-radius:50%}\n.s-todo::before{background:#e5484d}.s-pending{color:var(--mut)}.s-pending::before{background:transparent;border:2px solid var(--mut);width:5px;height:5px}\n.phase-dot{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:50%;font-size:12px;font-weight:800;color:#fff}\n.phase-dot.ph1{background:var(--ph1)}.phase-dot.ph2{background:var(--ph2)}\n.sv{min-width:130px}.sv strong{font-size:14.5px}.sv-bar{display:block;height:6px;background:var(--soft);border-radius:3px;margin-top:6px}.sv-bar i{display:block;height:100%;background:var(--brand);border-radius:3px}\n/* combined */\n.combo{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n.combo div{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px}\n.combo span{color:var(--mut);font-size:13.5px;display:block;min-height:42px}.combo b{font-size:28px;letter-spacing:-.02em}.combo em{font-style:normal;color:var(--mut);font-size:13px}\n.combo .total{background:var(--ink);border-color:var(--ink);color:#fcfcfc}.combo .total span,.combo .total em{color:#b9c3d6}.combo .total b{color:var(--mint)}\n/* chart */\n.chart{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px 22px 14px}\n.chart svg{width:100%;height:auto;display:block}\n.chart svg text{fill:var(--mut);font-size:11.5px;font-family:inherit}.chart svg text.note{font-style:italic}\n.chart .grid{stroke:var(--line);stroke-width:1}\n.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;font-weight:600;margin-bottom:8px}.legend i{display:inline-block;width:14px;height:3px;border-radius:2px;margin-right:7px;vertical-align:middle}\n.chart-cap{color:var(--mut);font-size:13px;margin:8px 0 0}\ndetails.how{margin:14px 0}details.how summary{cursor:pointer;font-weight:600;font-size:14px;color:var(--brand-text)}\ndetails.how p{color:var(--mut);font-size:14px;margin:8px 0 0}details.how .tbl{margin-top:10px;max-height:420px;overflow:auto}\n/* findings */\n.phase-head{display:flex;align-items:center;gap:12px;margin:40px 0 16px}\n.phase-head .tag{font-size:13px;font-weight:800;color:#fff;background:var(--pc);border-radius:8px;padding:4px 10px}\n.phase-head.ph1{--pc:var(--ph1)}.phase-head.ph2{--pc:var(--ph2)}\n.phase-head h3{margin:0}\n.finding{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:26px 28px;margin-bottom:18px;border-left:5px solid var(--pc);scroll-margin-top:60px}\n.finding.ph1{--pc:var(--ph1)}.finding.ph2{--pc:var(--ph2)}\n.f-head{display:grid;grid-template-columns:auto 1fr auto;gap:16px;align-items:start}\n.f-id{display:flex;align-items:center;gap:8px}.f-no{width:28px;height:28px;border-radius:50%;background:var(--pc);color:#fff;font-weight:800;font-size:13px;display:grid;place-items:center}\n.f-head h4{margin:2px 0 0;font-size:19px;line-height:1.3;letter-spacing:-.01em}\n.f-saving{text-align:right;white-space:nowrap}.f-saving b{font-size:26px;letter-spacing:-.02em;color:var(--brand-text);display:block;line-height:1}.f-saving span{font-size:12.5px;color:var(--mut)}\n.f-saving.tbd b{font-size:18px;color:var(--mut)}\n.f-meta{display:flex;flex-wrap:wrap;gap:8px 28px;margin:16px 0 0;padding:12px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n.meta-item span{font-size:12px;color:var(--mut);display:block}.meta-item b{font-size:14px}.meta-item a{color:inherit}\n.why{font-size:16px;margin:16px 0}\n.kv-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:14px 0}\n.kv{background:var(--soft);border-radius:10px;padding:12px 14px}.kv span{font-size:12px;color:var(--mut)}.kv p{margin:2px 0 0;font-weight:600;font-size:14.5px}\n.chips-wrap{margin:14px 0}.chips-label,.sub{font-size:12.5px;color:var(--mut);font-weight:600;display:block;margin-bottom:8px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{font-size:12.5px;background:var(--soft);border:1px solid var(--line);border-radius:6px;padding:3px 8px}\n.note{font-size:14px;border-radius:10px;padding:10px 14px;margin:12px 0;border-left:3px solid var(--info-line);background:var(--info-bg)}\n.note.n-warn{border-color:var(--warn-line);background:var(--warn-bg)}\n.note code,.why code,.next code,.kv code,.chips-label code{font-size:.88em;background:var(--soft);padding:1px 5px;border-radius:4px}\n.code{margin:14px 0;border-radius:12px;overflow:hidden;background:var(--code-bg)}\n.code-head{display:flex;justify-content:space-between;align-items:center;padding:8px 14px;border-bottom:1px solid rgba(255,255,255,.08);font-size:12.5px;color:#8f9bb3;font-weight:600}\n.copy{font:inherit;font-size:12px;color:var(--mint);background:transparent;border:1px solid rgba(134,255,201,.35);border-radius:6px;padding:3px 10px;cursor:pointer}\n.copy:hover,.copy:focus-visible{background:rgba(134,255,201,.12);outline:none}\n.code pre{margin:0;padding:14px 16px;overflow-x:auto;color:var(--code-fg);font-size:12.8px;line-height:1.55;max-height:640px}\n.next{display:flex;gap:16px;align-items:flex-start;background:color-mix(in srgb,var(--brand) 10%,var(--card));border:1px solid color-mix(in srgb,var(--brand) 40%,transparent);border-radius:12px;padding:14px 16px;margin-top:18px}\n.next span{flex:none;font-size:12px;font-weight:800;color:#06301d;background:var(--brand);border-radius:6px;padding:3px 8px;margin-top:2px}\n.next p{margin:0;font-weight:500}\n.refs{margin-top:14px;font-size:13px;display:flex;flex-wrap:wrap;gap:6px 16px;align-items:baseline}.refs span{color:var(--mut);font-weight:600}\n.barlist{list-style:none;padding:0;margin:4px 0 14px;display:grid;gap:6px}\n.barlist li{display:grid;grid-template-columns:minmax(150px,260px) 1fr 112px;gap:12px;align-items:center;font-size:13.5px}\n.bl-name{font-family:\"JetBrains Mono\",monospace;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.bl-bar{height:10px;background:var(--soft);border-radius:5px;overflow:hidden}.bl-bar i{display:block;height:100%;background:var(--c-traces);border-radius:5px}\n.bl-val{text-align:right;color:var(--mut);font-variant-numeric:tabular-nums;white-space:nowrap}\n.steps{margin:14px 0;padding-left:22px}.steps li{margin-bottom:6px}\n.policy{background:var(--soft);border-radius:12px;padding:14px 16px;margin:14px 0}\n.policy ol{margin:4px 0 0;padding-left:20px}.policy li{margin:3px 0}.policy-kept{margin-top:8px;font-size:13.5px;color:var(--mut)}\n/* adoption */\n.gaps{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}\n.gap{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px}\n.gap h4{margin:0 0 10px;font-size:17px}\n.gap .saw{color:var(--mut);font-size:14px;margin:0 0 12px}\n.gap .opp{margin:0;font-weight:600;font-size:14.5px;padding-left:14px;border-left:3px solid var(--brand)}\n.reinvest{margin-top:18px;background:var(--ink);color:#e6ecf5;border-radius:16px;padding:22px 26px;display:flex;gap:22px;align-items:center;flex-wrap:wrap}\n.reinvest b{font-size:34px;color:var(--mint);letter-spacing:-.02em;line-height:1}.reinvest p{margin:0;flex:1;min-width:260px}\n/* next steps */\n.timeline{list-style:none;margin:0;padding:0;position:relative}\n.timeline::before{content:\"\";position:absolute;left:99px;top:8px;bottom:8px;width:2px;background:var(--line)}\n.timeline li{display:grid;grid-template-columns:80px 30px 1fr;gap:0 12px;align-items:start;padding:10px 0}\n.timeline time{font-weight:700;font-size:14px;text-align:right;padding-top:12px}\n.timeline .dot{width:14px;height:14px;border-radius:50%;background:var(--card);border:3px solid var(--brand);margin:14px 0 0 1px;position:relative;z-index:1}\n.timeline .card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 16px}\n.timeline .who{font-size:12.5px;color:var(--mut);font-weight:700}.timeline .what{margin:2px 0 0;font-weight:600}\nfooter{margin:64px 0 0;background:var(--ink);color:#8b97ad;font-size:13px;padding:26px 0}\nfooter .wrap{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}\nfooter .logo{height:22px}\n:focus-visible{outline:2px solid var(--brand);outline-offset:2px}\n@media (max-width:820px){.road,.combo{grid-template-columns:1fr}.intro{grid-template-columns:1fr}.gaps{grid-template-columns:1fr}.phase p{min-height:0}\n.f-head{grid-template-columns:auto 1fr}.f-saving{grid-column:1/-1;text-align:left;display:flex;align-items:baseline;gap:8px}\n.fromto{text-align:left}.meter .keep{font-size:12px;padding:0 10px}.meter .save{font-size:12px;padding:0 10px}\n.barlist li{grid-template-columns:1fr auto}.bl-bar{grid-column:1/-1;grid-row:2}}\n@media (max-width:560px){.wrap{padding:0 18px}.hero,.finding{padding:20px}.timeline::before{left:75px}.timeline li{grid-template-columns:56px 30px 1fr}}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n@media print{*{-webkit-print-color-adjust:exact;print-color-adjust:exact}nav.toc{display:none}body{background:#fff}section{padding-top:28px}\n.finding,.phase,.gap,.code,.tbl,.chart{break-inside:avoid}details.how:not([open]) > *:not(summary){display:none}.copy{display:none}.code pre{max-height:none}}\n/* internal + upgrade additions (same tokens) */\n.internal-tag{background:rgba(157,134,255,.16);color:#d3c8ff;border:1px solid rgba(157,134,255,.45);border-radius:999px;padding:4px 12px;font-size:13px;font-weight:600}\n.s-done::before{background:var(--ph1)}.s-progress::before{background:var(--ph2)}\n.p-logs{background:color-mix(in srgb,var(--c-logs) 14%,transparent);color:var(--c-logs)}\n.p-universal{background:var(--soft);color:var(--fg)}\n.e-high{background:color-mix(in srgb,var(--ph3) 16%,transparent);color:var(--ph3)}\n.phase-dot.ph3{background:var(--ph3)}.phase-head.ph3{--pc:var(--ph3)}.finding.ph3{--pc:var(--ph3)}\n.vs{font-size:12.5px;font-weight:600;white-space:nowrap}.vs-verified{color:var(--brand-text)}.vs-rejected{color:#e5484d}.vs-needs-scoping{color:var(--c-metrics)}.vs-candidate{color:var(--mut)}\n.behind{background:var(--warn-bg);color:var(--c-metrics);font-weight:700;font-size:12.5px;border-radius:999px;padding:4px 10px;white-space:nowrap}\n.st-auto{color:var(--brand-text);font-weight:700}.st-manual{color:var(--c-metrics);font-weight:700}.st-na{color:var(--mut)}\n.appendix{background:var(--card);border:1px dashed var(--line);border-radius:16px;padding:22px 24px}\n.up-why{color:var(--mut);font-size:12.5px;margin-top:4px}\n.st-auto,.st-manual,.st-na{white-space:nowrap}\n.src-live{background:color-mix(in srgb,var(--brand) 16%,transparent);color:var(--brand-text);font-size:12px;font-weight:700;border-radius:999px;padding:3px 9px;white-space:nowrap}\n.samples{margin:16px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden}\n.samples-head{display:flex;justify-content:space-between;gap:12px;padding:10px 14px;background:var(--soft);font-size:12.5px;font-weight:700;color:var(--mut)}\n.pair{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}\n.pair.single{grid-template-columns:1fr}\n.pair pre{margin:0;padding:10px 14px;font-size:12px;line-height:1.5;white-space:pre-wrap;word-break:break-word;max-height:220px;overflow:auto}\n.pair .b{background:color-mix(in srgb,#e5484d 6%,var(--card))}.pair .a{background:color-mix(in srgb,var(--brand) 8%,var(--card));border-left:1px solid var(--line)}\n.pair .lbl{display:block;font-family:Manrope,sans-serif;font-size:11px;font-weight:700;color:var(--mut);margin-bottom:4px}\n.validated{border-radius:12px;padding:12px 16px;margin:14px 0;font-size:14px;border:1px solid color-mix(in srgb,var(--info-line) 40%,transparent);background:var(--info-bg)}\n.validated.no{background:var(--warn-bg);border-color:color-mix(in srgb,var(--warn-line) 45%,transparent)}\n.validated b{display:block;font-size:12.5px;color:var(--mut);margin-bottom:4px}\n.validated code{font-size:12px}\n.impact{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin:14px 0}\n.impact div{background:var(--card);padding:10px 14px}.impact span{display:block;font-size:12px;color:var(--mut)}.impact b{font-size:15px}\n.impact div:last-child b{color:var(--brand-text)}\n@media (max-width:820px){.pair{grid-template-columns:1fr}.pair .a{border-left:0;border-top:1px solid var(--line)}}\n.appendix ul{margin:8px 0 0;padding-left:20px;font-size:14px}\n";
export const SLIDE_CSS = "/* executive savings slide */\n#exec-slide{padding-top:56px}\n.slide-bar{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:16px}\n.slide-bar h2{margin:0}.slide-bar p{margin:4px 0 0;color:var(--mut);font-size:14px}\n.present{font:inherit;font-size:13.5px;font-weight:700;color:#06301d;background:var(--brand);border:0;border-radius:10px;padding:9px 16px;cursor:pointer}\n.present:hover{filter:brightness(1.06)}\n.slide-stage:fullscreen{display:grid;place-items:center;background:#070b19}\n.slide-stage:fullscreen .slide{width:min(100vw,177.78vh);border-radius:0;border:0}\n.slide-stage:fullscreen .slide-x{display:block}\n.slide{container-type:inline-size;aspect-ratio:16/9;position:relative;overflow:hidden;border-radius:20px;border:1px solid #232c4d;color:#e9eef7;\n background:radial-gradient(70% 90% at 100% 0%,rgba(19,233,137,.16),transparent 60%),linear-gradient(160deg,#111938,#0b1128 70%)}\n.slide-in{position:absolute;inset:0;padding:3.6cqw 4.8cqw 2.8cqw;display:grid;grid-template-columns:1.05fr 1fr;grid-template-rows:auto 1fr auto;gap:0 5cqw}\n.sl-top{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;font-size:1.25cqw;color:#9eabc4;font-weight:600;padding-bottom:1.8cqw;border-bottom:1px solid rgba(255,255,255,.1);margin-bottom:2.6cqw}\n.sl-top b{color:#e9eef7;font-weight:700}\n.sl-left{display:flex;flex-direction:column}\n.sl-kick{font-size:1.55cqw;color:#b9c4d8;margin:0 0 .8cqw}\n.sl-big{font-size:9.6cqw;font-weight:800;letter-spacing:-.045em;line-height:.9;color:#86ffc9;margin:0;font-variant-numeric:tabular-nums}\n.sl-big small{font-size:2.3cqw;letter-spacing:-.01em;color:#e9eef7;font-weight:700;margin-left:1cqw}\n.sl-from{font-size:1.85cqw;margin:1.6cqw 0 0;color:#e9eef7;font-weight:600;font-variant-numeric:tabular-nums}\n.sl-from span{color:#9eabc4;font-weight:500}\n.sl-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:1.2cqw;margin-top:auto}\n.sl-tiles div{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.09);border-radius:1.2cqw;padding:1.4cqw 1.5cqw}\n.sl-tiles b{display:block;font-size:2.9cqw;font-weight:800;letter-spacing:-.03em;line-height:1.05;font-variant-numeric:tabular-nums}\n.sl-tiles span{display:block;font-size:1.15cqw;color:#9eabc4;margin-top:.5cqw;line-height:1.3}\n.sl-right{display:flex;flex-direction:column}\n.sl-h{font-size:1.35cqw;font-weight:700;color:#b9c4d8;margin:0 0 1.4cqw}\n.pl{display:grid;grid-template-columns:7.2cqw 1fr 9.6cqw;align-items:center;gap:1.2cqw;margin-bottom:1.1cqw;font-variant-numeric:tabular-nums}\n.pl-name{font-size:1.45cqw;font-weight:700}.pl-name em{display:block;font-style:normal;font-weight:500;color:#9eabc4;font-size:1.1cqw}\n.pl-bar{height:1.6cqw;border-radius:.8cqw;background:var(--pc);display:flex;justify-content:flex-end;overflow:hidden;opacity:.95}\n.pl-bar i{display:block;height:100%;background:repeating-linear-gradient(135deg,#86ffc9 0 .45cqw,#4fe3a3 .45cqw .9cqw)}\n.pl-val{text-align:right;font-size:1.45cqw;font-weight:800}.pl-val em{display:block;font-style:normal;font-weight:500;color:#9eabc4;font-size:1.1cqw}\n.pl.zero .pl-val{color:#ffd36b}\n.drivers{list-style:none;margin:1.2cqw 0 0;padding:1.5cqw 0 0;border-top:1px solid rgba(255,255,255,.1);display:grid;gap:.6cqw}\n.drivers li{display:flex;justify-content:space-between;gap:1cqw;font-size:1.3cqw;color:#d3dbea}\n.drivers b{font-variant-numeric:tabular-nums;color:#86ffc9;white-space:nowrap}\n.sl-next{margin-top:1.6cqw;font-size:1.3cqw;line-height:1.4;background:rgba(255,211,107,.09);border:1px solid rgba(255,211,107,.28);border-radius:1.1cqw;padding:1.2cqw 1.4cqw;color:#f3e3b8}\n.sl-next b{color:#ffd36b}\n.sl-foot{grid-column:1/-1;display:flex;justify-content:space-between;gap:2cqw;font-size:1.05cqw;color:#7f8ca6;padding-top:1.6cqw}\n.slide-x{display:none;position:absolute;top:1.6cqw;right:1.6cqw;z-index:2;font:inherit;font-size:1.1cqw;color:#9eabc4;background:transparent;border:1px solid rgba(255,255,255,.18);border-radius:.6cqw;padding:.4cqw .9cqw;cursor:pointer}\n@container (max-width:680px){\n .slide-in{position:static;grid-template-columns:1fr;padding:24px 20px;gap:0}\n .sl-top{font-size:12px;flex-direction:column;align-items:flex-start;gap:2px;padding-bottom:12px;margin-bottom:18px}\n .sl-kick{font-size:14px;margin-bottom:6px}.sl-big{font-size:64px}.sl-big small{font-size:16px;margin-left:6px}.sl-from{font-size:15px;margin-top:10px}\n .sl-tiles{margin:20px 0 26px;gap:8px}.sl-tiles div{padding:10px;border-radius:10px}.sl-tiles b{font-size:20px}.sl-tiles span{font-size:11.5px}\n .sl-h{font-size:13px;margin-bottom:12px}.pl{grid-template-columns:72px 1fr 92px;gap:10px;margin-bottom:12px}\n .pl-name,.pl-val{font-size:13.5px}.pl-name em,.pl-val em{font-size:11px}.pl-bar{height:12px;border-radius:6px}\n .drivers{margin-top:10px;padding-top:12px;gap:6px}.drivers li{font-size:12.5px}\n .sl-next{font-size:12.5px;padding:10px 12px;border-radius:10px;margin-top:16px}.sl-foot{font-size:11px;flex-direction:column;gap:4px;padding-top:16px}}\n@container (max-width:680px){.slide{aspect-ratio:auto}}\n@media (max-width:720px){.slide{aspect-ratio:auto}}\n@media print{#exec-slide{break-after:page}.present{display:none}}\n\n/* part divider + draft flag on the slide */\n.part{margin:72px 0 0;padding:28px 0 0;border-top:2px solid var(--line)}\n.part span{font-size:12.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--brand-text)}\n.part h2{margin:.25em 0 .2em}\n.part p{margin:0;color:var(--mut);font-size:15px;max-width:70ch}\n.sl-draft{color:#ffd36b;font-weight:700}\n@media print{.part{break-before:page}}\n";
